#include <cctype>
#include <iostream>
#include <string>

bool isPalindrome(const std::string& word) {
    std::size_t n = word.size();
    for (std::size_t i = 0; i < n / 2; i++) {
        int front = std::tolower(static_cast<unsigned char>(word[i]));
        int back = std::tolower(static_cast<unsigned char>(word[n - 1 - i]));
        if (front != back) {
            return false;
        }
    }
    return true;
}

int main() {
    std::string word;
    std::cin >> word;
    std::cout << (isPalindrome(word) ? "true" : "false") << "\n";
    return 0;
}

